export type TriageLevel = 'EMERGENCY' | 'URGENT' | 'ROUTINE' | 'SELF_CARE';

export type TriageStatus = 'final' | 'need_more_info' | 'error';

export type RouteMode = 'driving' | 'transit' | 'walking';

// 医院信息
export interface Hospital {
  rank: number;
  name: string;
  is_3a: boolean;
  address: string;
  distance_m: number;
  location: {
    lat: number;
    lng: number;
  };
  phone: string;
  reason: string;
}

// 导航结果
export interface NavigationResult {
  radius_km: number;
  hospitals: Hospital[];
  route_plan?: {
    to_hospital_rank: number;
    mode: RouteMode;
    eta_min: number;
    summary: string;
  };
}

// 证据
export interface Evidence {
  source_type: string;
  source_description: string;
  content: string;
  confidence: number;
}

// 天气预警
export interface WeatherAlert {
  condition: string;
  temperature_c: number;
  advice: string;
}

// 视觉发现
export interface VisualFindings {
  observations: string[];
  confidence: number;
}

// 请求
export interface TriageRequest {
  session_id: string;
  text: string;
  image_base64?: string;
  gps_lat?: number;
  gps_lng?: number;
}

// 响应
export interface TriageResponse {
  status: TriageStatus;
  session_id: string;
  triage_level?: TriageLevel;
  triage_reason?: string;
  triage_source?: string;
