    def _generate_travel_tips(
        self,
        text: str,
        temp: int,
        humidity: int,
        wind_scale: int
    ) -> List[str]:
        """Generate travel tips based on weather conditions.

        Args:
            text: Weather condition text (e.g., "多云", "小雨")
            temp: Temperature in Celsius
            humidity: Humidity percentage
            wind_scale: Wind scale (0-12)

        Returns:
            List of travel tip strings (max 5 per spec)
        """
        tips = []

        # Rain-related tips
        if any(keyword in text for keyword in ["雨", "雷", "毛毛雨", "阵雨", "暴雨"]):
            tips.append("带伞出行")

        # Snow-related tips
        if any(keyword in text for keyword in ["雪", "雪粒"]):
            tips.append("注意保暖")
            tips.append("路面可能结冰")

        # Temperature tips
        if temp >= 30:
            tips.append("注意防暑")
        elif temp <= 5:
            tips.append("注意保暖")
        elif temp <= 10:
            tips.append("穿外套保暖")

        # Wind tips
        if wind_scale >= 5:
            tips.append("注意防风")

        # Humidity tips
        if humidity >= 80:
            tips.append("湿度较大")

        # Fog/mist tips
        if any(keyword in text for keyword in ["雾", "雾凇"]):
            tips.append("能见度低，小心驾驶")

        # Default tips if no specific conditions
        if not tips:
            tips.append("适宜出行")

        # Max 5 tips per spec
        return tips[:5]

